# ArtifactCleanup.psm1
# Core retention-policy engine for CI artifact cleanup.
#
# Approach:
#   Get-ArtifactCleanupPlan is a pure function: mock artifact records in,
#   deterministic deletion plan out. All policies are optional; when a policy
#   parameter is omitted that rule simply doesn't apply.

function Get-ArtifactCleanupPlan {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [object[]]$Artifacts,

        [Nullable[int]]$MaxAgeDays,

        [datetime]$ReferenceDate = (Get-Date).ToUniversalTime()
    )

    $deleted  = [System.Collections.Generic.List[object]]::new()
    $retained = [System.Collections.Generic.List[object]]::new()

    foreach ($artifact in $Artifacts) {
        $created = [datetime]::Parse($artifact.CreatedAt).ToUniversalTime()
        $ageDays = ($ReferenceDate - $created).TotalDays

        if ($null -ne $MaxAgeDays -and $ageDays -gt $MaxAgeDays) {
            $deleted.Add([pscustomobject]@{
                Name          = $artifact.Name
                SizeBytes     = [long]$artifact.SizeBytes
                CreatedAt     = $created
                WorkflowRunId = $artifact.WorkflowRunId
                Reason        = 'MaxAge'
            })
        }
        else {
            $retained.Add($artifact)
        }
    }

    [pscustomobject]@{
        Retained = $retained.ToArray()
        Deleted  = $deleted.ToArray()
    }
}

Export-ModuleMember -Function Get-ArtifactCleanupPlan

